const scripts={ouverture:'Hola, le llamo de Renov Aides. ¿Es usted propietario de una vivienda?',q1_tipo_propiedad:'¿Qué tipo de propiedad desea reformar: piso, casa o local?',q2_zona:'¿En qué zona o ciudad se encuentra la propiedad?',q3_plazo:'¿En qué plazo le gustaría realizar la reforma?',q4_presupuesto:'¿Dispone de un presupuesto orientativo para el proyecto?',cierre_rdv:'Perfecto, le propongo una llamada con nuestro asesor. ¿Le va bien mañana por la mañana?',despedida:'Muchas gracias por su tiempo. Que tenga un buen día.'};
const keys=Object.keys(scripts);
const out=[];
for(const key of keys){
  const audio=await this.helpers.httpRequest({method:'POST',url:'https://api.elevenlabs.io/v1/text-to-speech/'+$env.ELEVENLABS_VOICE_ID,headers:{'xi-api-key':$env.ELEVENLABS_API_KEY,'Content-Type':'application/json',Accept:'audio/mpeg'},body:{text:scripts[key],model_id:'eleven_multilingual_v2'},json:false,encoding:'arraybuffer'});
  out.push({key,bytes:audio.byteLength,hint:'Upload '+key+'.mp3 to STORAGE_BUCKET_URL'});
}
return [{json:{cached:keys.length,files:out}}];
